    var lab = narrow ? 102 : Math.min(200, Math.round(BW * 0.24)), tw = narrow ? 28 : 34, rh = 24, top = 2, mlh = 46, bmax = 1;
    var avail = BW - lab - tw, cw2 = Math.max(narrow ? 13.5 : 18, (avail - 1) / Math.max(1, nm)), GW = nm * cw2;
    var nr = bd.rows.length, GH = nr * rh, H = top + GH + mlh;
