    buildPanel();
    applyHash(readHash());
    var sb = $("berlin-search"), st;
    sb.value = S.q;
    sb.addEventListener("input", function () {
      clearTimeout(st);
      st = setTimeout(function () { S.q = fold(sb.value).trim(); onFilterChange(); }, 150);
    });
    $("btn-corr").addEventListener("click", function () {
      S.corr = !S.corr; onFilterChange();
      setTimeout(function () { if (S.view === "map") fitMain(); else fitTL(); }, 0);  // zoom to corridor / back to pins
    });
    $("btn-new").addEventListener("click", function () { S.newOnly = !S.newOnly; onFilterChange(); });
    $("btn-link").addEventListener("click", copyLink);
    $("tl-speed").addEventListener("change", function (e) { S.speed = +e.target.value; writeHash(); });
    $("tl-mode").addEventListener("change", function (e) { S.win = +e.target.value; renderTL(); drawHist(); writeHash(); });
    $("theme-select").addEventListener("change", function (e) { setTheme(e.target.value, true); });
    $("btn-view-map").addEventListener("click", function () { setView("map"); });
    $("btn-view-tl").addEventListener("click", function () { setView("timeline"); });
    $("btn-view-an").addEventListener("click", function () { setView("analytics"); });
