  var CRUDE = /([\p{L}.)-])\s+\d{1,4}(?!\d)(?:\s?[a-zA-Z](?![\p{L}]))?(?:\s?[-\u2013/]\s?\d{1,4}[a-zA-Z]?)?(?![\d.:,]\d|\.\s?\p{L}|\s?(?:Uhr|km|m\b|%|h\b|Jahre|years?\b|Euro|\u20ac))/gu;
